def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full-height or full-width separator.
    for c in range(w):
        if all(grid[r][c] == grid[0][c] and grid[r][c] != 0 for r in range(h)):
            left, right = c, w - c - 1
            n = min(left, right)
            return [[2 if grid[r][c - n + j] != 0 and grid[r][c + 1 + j] != 0 else 0
                     for j in range(n)] for r in range(h)]

    for r in range(h):
        if all(grid[r][c] == grid[r][0] and grid[r][c] != 0 for c in range(w)):
            top, bottom = r, h - r - 1
            n = min(top, bottom)
            return [[2 if grid[r - n + i][c] != 0 and grid[r + 1 + i][c] != 0 else 0
                     for c in range(w)] for i in range(n)]

    return grid
